#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
IMA 知识库原文件下载器（腾讯 ima.copilot）

功能：
  1. enum     —— 递归遍历知识库目录树，产出 ima_enum_<kb>.json 清单
  2. download —— 逐文件取 jump_url（服务端签名直链）下载原文件，保留目录结构
  3. all      —— enum + download（默认）

用法：
  python ima_sync.py                 # 默认 all，使用 ima_config.json 里的知识库
  python ima_sync.py enum            # 仅枚举
  python ima_sync.py download        # 仅下载（需先有 ima_enum_<kb>.json）
  python ima_sync.py all --root D:/IMA --workers 8

前置（二者都必须由使用者自己提供，本 skill 不含任何预设）：
  - ima_tokens.json  : 你自己的 IMA 登录态 cookie（见 references/api.md 的"如何获取 token"）
  - ima_config.json  : {"root":"...", "kbs":[{"id":"...","name":"..."}]}（你的知识库）

注意：
  - 必须关闭代理（urllib 会读环境代理），脚本启动即清空相关环境变量。
  - jump_url 约 4 小时有效，脚本每次下载都现取，并定时刷新 access_token。
"""

import json, urllib.request, urllib.error, ssl, re, os, time, threading, sys, argparse

# ---- 关闭代理（IMA 后端直连，走代理会 403/超时）----
for _k in ["HTTP_PROXY", "HTTPS_PROXY", "http_proxy", "https_proxy", "ALL_PROXY", "all_proxy"]:
    os.environ.pop(_k, None)

CTX = ssl.create_default_context()
CTX.check_hostname = False
CTX.verify_mode = ssl.CERT_NONE
UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/150.0.0.0 Safari/537.36"

HERE = os.path.dirname(os.path.abspath(__file__))

# ---------------- 配置 ----------------
def find_file(name):
    for p in [os.path.join(os.getcwd(), name), os.path.join(HERE, name)]:
        if os.path.exists(p):
            return p
    return None

TOKENS_FILE = find_file("ima_tokens.json")
CONFIG_FILE = find_file("ima_config.json")

# 本 skill 不携带任何预设知识库 / 登录态。请用自己的 IMA 登录态创建 ima_config.json。
# 下面仅作结构示例（占位 ID，运行时必须替换），实际不会用于下载。
DEFAULT_ROOT = "IMA_下载"
DEFAULT_KBS = [
    ("<your-knowledge-base-id>", "（示例占位，请替换）"),
]

WORKERS = 6
REFRESH_EVERY = 3300  # 秒（~55 分钟，access_token 有效期约 2h）

TOK_LOCK = threading.Lock()
USED = {}
USED_LOCK = threading.Lock()

# ---------------- 鉴权 ----------------
def E9(e):
    """IMA bkn 哈希：t=5381; for ch: t+=(t<<5)+ord(ch); return t & 2147483647"""
    t = 5381
    for ch in e:
        t += (t << 5) + ord(ch)
    return t & 2147483647

def load_tokens():
    if not TOKENS_FILE:
        raise SystemExit("缺少 ima_tokens.json（请把 IMA 桌面端 cookie 导出到脚本同目录或 cwd）。详见 references/api.md")
    return json.load(open(TOKENS_FILE, encoding="utf-8"))

TOK = load_tokens()

def refresh():
    global TOK
    with TOK_LOCK:
        cookie = TOK["cookie"]
        uid = re.search(r"IMA-UID=([^;]+)", cookie)
        uid = uid.group(1) if uid else ""
        try:
            body = {"user_id": uid, "refresh_token": TOK["refresh_token"]}
            req = urllib.request.Request("https://ima.qq.com/cgi-bin/auth_login/refresh",
                data=json.dumps(body).encode(), headers={"content-type": "application/json", "user-agent": UA}, method="POST")
            with urllib.request.urlopen(req, context=CTX, timeout=20) as r:
                j = json.loads(r.read().decode())
            if j.get("code") == 0 and j.get("token"):
                TOK["access_token"] = j["token"]
                TOK["cookie"] = re.sub(r"IMA-TOKEN=[^;]+", "IMA-TOKEN=" + j["token"], cookie)
                TOK["cookie"] = re.sub(r"IMA-REFRESH-TOKEN=[^;]+", "IMA-REFRESH-TOKEN=" + TOK["refresh_token"], TOK["cookie"])
                if TOKENS_FILE:
                    json.dump(TOK, open(TOKENS_FILE, "w", encoding="utf-8"))
        except Exception as e:
            print("refresh err:", e)

def headers():
    with TOK_LOCK:
        cookie = TOK["cookie"]
    bkn = E9(re.search(r"IMA-TOKEN=([^;]+)", cookie).group(1))
    return {"x-ima-cookie": cookie, "from_browser_ima": "1", "x-ima-bkn": str(bkn),
            "referer": "https://ima.qq.com/wikis", "user-agent": UA,
            "content-type": "application/json", "accept": "application/json"}

def post(path, body):
    req = urllib.request.Request("https://ima.qq.com" + path, data=json.dumps(body).encode(),
                                 headers=headers(), method="POST")
    with urllib.request.urlopen(req, context=CTX, timeout=20) as r:
        return json.loads(r.read().decode())

# ---------------- 文件名处理 ----------------
def safe(name):
    if not name:
        return "untitled"
    return re.sub(r'[\\/:*?"<>|]', "_", name).strip().rstrip(" .")

def alloc_path(ddir, fname):
    with USED_LOCK:
        p = os.path.join(ddir, fname)
        if p in USED:
            base, ext = os.path.splitext(fname); i = 1
            while True:
                p = os.path.join(ddir, f"{base}({i}){ext}")
                if p not in USED:
                    break
                i += 1
        USED[p] = True
    return p

# ---------------- 枚举（文件夹树递归）----------------
def list_folder(kb, folder_id):
    out = []; cursor = ""; pages = 0
    while True:
        body = {"knowledgeBaseId": kb, "knowledgeListReq": {"limit": 50, "cursor": cursor}}
        if folder_id:
            body["knowledgeListReq"]["folderId"] = folder_id
        j = post("/cgi-bin/knowledge_tab_reader/get_knowledge_base_home_page", body)
        lr = j.get("list_rsp", {})
        items = lr.get("knowledge_list", [])
        out.extend(items); pages += 1
        if lr.get("is_end") or not lr.get("next_cursor") or not items:
            break
        cursor = lr["next_cursor"]
        if pages > 200:
            break
    return out

def enum_kb(kb):
    folders = {}
    files = []
    def collect(folder_id, rel):
        items = list_folder(kb, folder_id)
        for it in items:
            if it.get("media_type") == 99 and it.get("folder_info"):
                fid = it["folder_info"]["folder_id"]
                nm = it["folder_info"]["name"] or fid
                folders[fid] = {"name": nm, "parent": folder_id}
                collect(fid, os.path.join(rel, safe(nm)))
            else:
                files.append({
                    "media_id": it.get("media_id"),
                    "title": it.get("title"),
                    "file_size": it.get("file_size"),
                    "media_type": it.get("media_type"),
                    "parent": it.get("parent_folder_id"),
                    "rel": rel,
                })
    collect("", "")
    return folders, files

def do_enum(kbs):
    for kb, name in kbs:
        t0 = time.time()
        folders, files = enum_kb(kb)
        total_size = sum(int(f.get("file_size") or 0) for f in files)
        print(f"[enum] {name}: folders={len(folders)} files={len(files)} "
              f"~{total_size/1e6:.1f}MB in {time.time()-t0:.1f}s")
        json.dump({"folders": folders, "files": files},
                  open(os.path.join(HERE, f"ima_enum_{kb}.json"), "w", encoding="utf-8"),
                  ensure_ascii=False)

# ---------------- 下载 ----------------
def get_jump_url(kb, media_id):
    j = post("/cgi-bin/knowledge_tab_reader/get_knowledge",
             {"mediaId": media_id, "knowledgeBaseId": kb, "needDefaultCover": False})
    return j.get("knowledge", {}).get("jump_url", "")

def download_file(kb, f, target_root):
    media_id = f["media_id"]; title = f.get("title") or media_id
    rel = f.get("rel", "")
    fname = safe(title)
    ddir = os.path.join(target_root, rel) if rel else target_root
    os.makedirs(ddir, exist_ok=True)
    path = alloc_path(ddir, fname)
    expected = int(f.get("file_size") or 0)
    # 断点续传：已存在且字节数一致则跳过
    if expected > 0 and os.path.exists(path) and os.path.getsize(path) == expected:
        return ("skip", path, expected)
    if os.path.exists(path):
        try:
            os.remove(path)
        except Exception:
            pass
    last = None
    for _ in range(3):
        try:
            ju = get_jump_url(kb, media_id)
            if not ju:
                return ("nourl", path, 0)
            # 非 http 协议（笔记/链接，如 chrome://）—— 把链接存成文本
            if not ju.lower().startswith(("http://", "https://")):
                lp = path + ".link.txt"
                open(lp, "w", encoding="utf-8").write(ju)
                return ("ok", lp, len(ju))
            req = urllib.request.Request(ju, headers={"user-agent": UA, "referer": "https://ima.qq.com/wikis"})
            with urllib.request.urlopen(req, context=CTX, timeout=120) as r:
                data = r.read()
                ctype = (r.headers.get("Content-Type") or "").lower()
            # 字节数不符：微信公众号文章(wechatarticle_/media_type:6)等返回的是 HTML 正文
            if expected > 0 and len(data) != expected:
                head = data[:512].lstrip().lower()
                if "html" in ctype or head.startswith(b"<!doctype") or head.startswith(b"<html") or b"<html" in head[:300]:
                    hp = path + ".html"
                    open(hp, "wb").write(data)
                    return ("ok", hp, len(data))
                last = f"size {len(data)}!={expected}"
                time.sleep(1)
                continue
            open(path, "wb").write(data)
            return ("ok", path, len(data))
        except Exception as e:
            last = str(e)[:160]
            time.sleep(2)
    return ("fail", path, last)

def do_download(kbs, root):
    start = time.time()
    FAILURES = []
    for kb, name in kbs:
        enum_path = os.path.join(HERE, f"ima_enum_{kb}.json")
        if not os.path.exists(enum_path):
            print(f"[download] 缺 {enum_path}，请先运行 enum"); continue
        target = os.path.join(root, name)
        os.makedirs(target, exist_ok=True)
        enum = json.load(open(enum_path, encoding="utf-8"))
        files = enum["files"]
        total = len(files); done = 0; ok = skip = fail = nourl = 0
        print(f"=== {name}: {total} files -> {target}")
        last_refresh = time.time()
        with ThreadPoolExecutor(max_workers=WORKERS) as ex:
            fut = {ex.submit(download_file, kb, f, target): f for f in files}
            for fu in as_completed(fut):
                st, p, sz = fu.result()
                f = fut[fu]; done += 1
                if st == "ok": ok += 1
                elif st == "skip": skip += 1
                elif st == "fail":
                    fail += 1
                    FAILURES.append({"kb": kb, "name": name, "media_id": f["media_id"], "title": f.get("title"), "err": sz})
                elif st == "nourl": nourl += 1
                if time.time() - last_refresh > REFRESH_EVERY:
                    refresh(); last_refresh = time.time()
                if done % 50 == 0 or done == total:
                    print(f"  {name}: {done}/{total} ok={ok} skip={skip} fail={fail} nourl={nourl} ({time.time()-start:.0f}s)")
        print(f"  >>> {name} DONE ok={ok} skip={skip} fail={fail} nourl={nourl} "
              f"~{sum(int(x.get('file_size') or 0) for x in files)/1e6:.0f}MB")
    json.dump(FAILURES, open(os.path.join(HERE, "ima_failures.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    if FAILURES:
        print("FAILURES:", len(FAILURES))
        for x in FAILURES:
            print("  ", x["name"], x["title"], "->", x["err"])
    print("ALL DONE in", time.time() - start, "s")

# ---------------- 入口 ----------------
def main():
    global WORKERS
    ap = argparse.ArgumentParser(description="IMA 知识库原文件下载器")
    ap.add_argument("mode", nargs="?", default="all", choices=["enum", "download", "all"])
    ap.add_argument("--root", default=None, help="下载根目录")
    ap.add_argument("--workers", type=int, default=WORKERS)
    args = ap.parse_args()

    WORKERS = args.workers

    if CONFIG_FILE:
        cfg = json.load(open(CONFIG_FILE, encoding="utf-8"))
        root = args.root or cfg.get("root") or DEFAULT_ROOT
        kbs = [(k["id"], k["name"]) for k in cfg.get("kbs", [])]
        if not kbs:
            raise SystemExit("ima_config.json 中未配置 kbs，请参考 SKILL.md 填入你的知识库 ID。")
    else:
        raise SystemExit(
            "未找到 ima_config.json。\n"
            "本 skill 不含任何预设知识库，请用你自己的 IMA 登录态创建 ima_config.json：\n"
            "  {\"root\":\"下载目录\", \"kbs\":[{\"id\":\"你的知识库ID\",\"name\":\"名称\"}]}\n"
            "详见 SKILL.md 与 references/api.md。"
        )

    print(f"root={root}  kbs={[n for _, n in kbs]}")
    if args.mode in ("enum", "all"):
        do_enum(kbs)
    if args.mode in ("download", "all"):
        do_download(kbs, root)

if __name__ == "__main__":
    from concurrent.futures import ThreadPoolExecutor, as_completed
    main()

