#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
批量下载 IMA 知识库（经 IMA-MCP 通道，任何人可用）。

关键事实（踩坑结论，勿改）：
1. 本 skill 依赖 IMA 提供的 MCP 通道，不依赖特定账号/机器：
   - 优先：环境变量显式指定 IMA_MCP_URL + IMA_MCP_AUTH（自行搭建 IMA-MCP 时）；
   - 其次：自动从 CODEBUDDY_MCP_CONFIG 解析出暴露 ima 工具的 MCP 服务器
     （WorkBuddy 中连接了 IMA 连接器的用户会自动拿到预授权凭证，无需硬编码 token）；
   - 都没有则友好报错，提示先连接 IMA 连接器或设置环境变量。
2. IMA OpenAPI 静态密钥直连会被平台拒绝（errcode 200002 skill auth failed），
   故不支持裸 OpenAPI 调用——这是平台策略，不是 bug。
3. MCP 工具名带命名空间前缀，形如 ima-mcp_get_knowledge_list / ima-mcp_fetch_media_content；
   前缀从通道自动推导（也可 --mcp-prefix 覆盖）。
4. fetch_media_content 只返回【文本提取】，不返回原文件二进制、也不给下载 URL。
   因此“原格式优先”在本通道下不可得，实际统一导出为 Markdown(.md)。
   若将来通道支持原文件 URL，脚本会自动按 URL 下载二进制（见 save_content）。
5. get_knowledge_list 分页：is_end / next_cursor；文件夹条目的 media_type=99 且含 folder_info。

用法：
  python download_ima_kb.py --search "知识库名" --out DIR
  python download_ima_kb.py --kb-id 7396... --out DIR
  python download_ima_kb.py --kb-id 7396... --out DIR --discover   # 仅列出不下载
断点续传：已成功 media_id 写入 <OUT>/_download_ok.txt，重跑自动跳过。
"""
import json, os, sys, time, re, argparse, urllib.request, urllib.error

# 本 skill 为【免费版】：无激活码、无试用篇数限制，整库直接导出。

# ---------- 解析 IMA MCP 通道（三种来源，按优先级） ----------
# 1) 显式环境变量 / CLI：IMA_MCP_URL + IMA_MCP_AUTH（+ 可选 IMA_MCP_SESSION / IMA_MCP_PREFIX）
# 2) 自动：从 CODEBUDDY_MCP_CONFIG 中找出暴露 ima get_knowledge_list 工具的 MCP 服务器
#    （通常是 connector-proxy；其 headers 已在购买者本地预授权，无需硬编码 token）
# 3) 都没有 → 友好报错，提示先连接 IMA 连接器
PROXY_URL = None
AUTH_HEADERS = {}
TOOL_PREFIX = "ima-mcp_"


def _find_ima_server(cfg):
    for _name, srv in cfg.get("mcpServers", {}).items():
        for k in srv.get("tools", {}):
            if k.endswith("get_knowledge_list"):
                return srv
    return None


def setup_proxy(explicit=None):
    """解析并设置全局 PROXY_URL / AUTH_HEADERS / TOOL_PREFIX。无通道时抛友好错误。"""
    global PROXY_URL, AUTH_HEADERS, TOOL_PREFIX
    explicit = explicit or {}
    url = explicit.get("url") or os.environ.get("IMA_MCP_URL")
    auth = explicit.get("auth") or os.environ.get("IMA_MCP_AUTH")
    sess = (explicit.get("session") or os.environ.get("IMA_MCP_SESSION")
            or os.environ.get("CODEBUDDY_SESSION_ID") or "")
    if url and auth:
        headers = {"Authorization": auth}
        if sess:
            headers["X-WorkBuddy-Session-Id"] = sess
        prefix = explicit.get("prefix") or os.environ.get("IMA_MCP_PREFIX") or "ima-mcp_"
        PROXY_URL, AUTH_HEADERS, TOOL_PREFIX = url, headers, prefix
        return
    raw = os.environ.get("CODEBUDDY_MCP_CONFIG")
    if raw:
        try:
            cfg = json.loads(raw)
        except Exception:
            cfg = None
        if cfg:
            srv = _find_ima_server(cfg)
            if srv:
                u = srv.get("url")
                hdrs = dict(srv.get("headers", {}))
                prefix = "ima-mcp_"
                for k in srv.get("tools", {}):
                    if k.endswith("get_knowledge_list"):
                        prefix = k[: -len("get_knowledge_list")]
                        break
                PROXY_URL, AUTH_HEADERS, TOOL_PREFIX = u, hdrs, prefix
                return
    raise SystemExit(
        "未找到 IMA MCP 通道。请二选一：\n"
        "  ① 在 WorkBuddy 中连接「IMA 知识库」连接器后重试（推荐，自动读取凭证）；\n"
        "  ② 设置环境变量 IMA_MCP_URL / IMA_MCP_AUTH（可选 IMA_MCP_SESSION、IMA_MCP_PREFIX）\n"
        "    指向你自己的 IMA-MCP 端点。\n"
        "本 skill 依赖 IMA 连接器/MCP 通道，无法用裸 IMA OpenAPI 静态密钥直接调用"
        "（平台会以 200002 skill auth failed 拒绝）。"
    )

MEDIA_EXT = {
    1: ".pdf", 3: ".docx", 4: ".pptx", 5: ".xlsx", 7: ".md", 9: ".png",
    11: ".md", 13: ".txt", 14: ".xmind", 15: ".mp3", 2: ".html", 6: ".html",
    16: ".html", 17: ".html",
}
MEDIA_NAME = {
    1: "PDF", 2: "网页", 3: "Word", 4: "PPT", 5: "Excel", 6: "微信公众号文章",
    7: "MarkDown", 9: "图片", 11: "笔记", 12: "AI会话", 13: "TXT", 14: "Xmind",
    15: "录音", 16: "视频解析", 17: "播客", 99: "文件夹",
}

session_id = None


def _post(payload):
    global session_id
    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(PROXY_URL, data=data, method="POST")
    for h, v in AUTH_HEADERS.items():
        req.add_header(h, v)
    req.add_header("Content-Type", "application/json")
    req.add_header("Accept", "application/json, text/event-stream")
    if session_id:
        req.add_header("Mcp-Session-Id", session_id)
    for attempt in range(4):
        try:
            with urllib.request.urlopen(req, timeout=60) as resp:
                if "mcp-session-id" in resp.headers:
                    session_id = resp.headers["mcp-session-id"]
                return resp.read().decode("utf-8")
        except urllib.error.HTTPError as e:
            if e.code == 429:
                time.sleep(3 * (attempt + 1))
                continue
            raise
        except Exception:
            time.sleep(2 * (attempt + 1))
    raise RuntimeError("MCP request failed after retries")


def _parse_sse(body):
    results = []
    for block in re.split(r"\n\n+", body):
        m = re.search(r"data:\s*(\{.*\})\s*$", block, re.S)
        if m:
            try:
                results.append(json.loads(m.group(1)))
            except Exception:
                pass
    return results


def mcp_call(method, params, notification=False, _attempt=0):
    payload = {"jsonrpc": "2.0", "method": method, "params": params}
    if not notification:
        payload["id"] = int(time.time() * 1000) % 1000000
    try:
        body = _post(payload)
    except RuntimeError:
        if _attempt < 2:
            time.sleep(1)
            init()
            return mcp_call(method, params, notification, _attempt + 1)
        raise
    if notification:
        return None
    msgs = _parse_sse(body)
    for msg in msgs:
        if msg.get("id") == payload["id"]:
            if "error" in msg:
                err = msg["error"]
                if _attempt < 2 and "session" in str(err).lower():
                    init()
                    return mcp_call(method, params, notification, _attempt + 1)
                raise RuntimeError(f"MCP error: {err}")
            return msg.get("result")
    for msg in msgs:
        if "result" in msg:
            return msg["result"]
    raise RuntimeError(f"No result in response: {body[:500]}")


def tool_result_text(result):
    if not result:
        return None
    content = result.get("content")
    if isinstance(content, list) and content:
        text = content[0].get("text", "")
    else:
        text = result.get("content", "")
    if isinstance(text, str):
        try:
            return json.loads(text)
        except Exception:
            return text
    return text


def init():
    mcp_call("initialize", {
        "protocolVersion": "2024-11-05",
        "capabilities": {},
        "clientInfo": {"name": "ima-kb-dl", "version": "1.0"},
    })
    mcp_call("notifications/initialized", {}, notification=True)


def list_knowledge(kb_id, folder_id=None, cursor=""):
    params = {"knowledge_base_id": kb_id, "limit": 50, "cursor": cursor}
    if folder_id:
        params["folder_id"] = folder_id
    r = mcp_call("tools/call", {
        "name": f"{TOOL_PREFIX}get_knowledge_list",
        "arguments": params,
    })
    return tool_result_text(r)


def fetch_content(media_id):
    r = mcp_call("tools/call", {
        "name": f"{TOOL_PREFIX}fetch_media_content",
        "arguments": {"media_id": media_id},
    })
    return tool_result_text(r)


def search_kb(query, limit=20):
    r = mcp_call("tools/call", {
        "name": f"{TOOL_PREFIX}search_knowledge_base",
        "arguments": {"query": query, "limit": limit, "cursor": ""},
    })
    return tool_result_text(r)


def sanitize(name):
    name = re.sub(r'[\\/:*?"<>|\r\n\t]', "_", name).strip()
    name = name.rstrip(". ")
    return name or "未命名"


def walk(kb_id, folder_id, rel_path, items, depth=0):
    # 防御：避免异常递归（理论上 is_end 会终止）
    if depth > 20:
        return
    cursor = ""
    while True:
        data = list_knowledge(kb_id, folder_id, cursor)
        if isinstance(data, str):
            data = json.loads(data)
        if not isinstance(data, dict):
            data = {}
        kl = data.get("knowledge_list", [])
        for it in kl:
            mt = it.get("media_type")
            title = it.get("title", "未命名")
            media_id = it.get("media_id")
            if mt == 99 or (it.get("folder_info") is not None):
                fid = it.get("folder_info", {}).get("folder_id") or media_id
                fname = sanitize(title)
                items.append({"type": "folder", "title": title, "rel": rel_path})
                walk(kb_id, fid, os.path.join(rel_path, fname), items, depth + 1)
            else:
                items.append({
                    "type": "file", "title": title, "media_id": media_id,
                    "media_type": mt, "rel": rel_path,
                })
        if data.get("is_end") or not data.get("next_cursor"):
            break
        cursor = data.get("next_cursor", "")


def save_content(res, full, mt, title):
    text, url = None, None
    if isinstance(res, dict):
        if res.get("url"):
            url = res["url"]
        if isinstance(res.get("content"), str):
            text = res["content"]
        elif isinstance(res.get("text"), str):
            text = res["text"]
        elif isinstance(res.get("data"), dict):
            d = res["data"]
            if isinstance(d.get("content"), str):
                text = d["content"]
            if d.get("url"):
                url = d["url"]
        if text is None and url is None:
            text = json.dumps(res, ensure_ascii=False, indent=2)
    elif isinstance(res, str):
        if res.startswith("http://") or res.startswith("https://"):
            url = res
        else:
            text = res

    # 优先原格式（URL 指向二进制文件）
    if url:
        try:
            req = urllib.request.Request(url, headers={
                "User-Agent": "Mozilla/5.0",
                "Authorization": AUTH_HEADERS.get("Authorization", ""),
            })
            with urllib.request.urlopen(req, timeout=120) as resp:
                data = resp.read()
            ct = resp.headers.get("Content-Type", "")
            out = full
            m = re.search(r"\.([A-Za-z0-9]{1,6})(?:\?|$)", url)
            if m and not out.lower().endswith("." + m.group(1).lower()):
                out = os.path.splitext(full)[0] + "." + m.group(1).lower()
            elif "pdf" in ct and not out.lower().endswith(".pdf"):
                out = os.path.splitext(full)[0] + ".pdf"
            with open(out, "wb") as f:
                f.write(data)
            return out
        except Exception:
            try:
                with open(full, "w", encoding="utf-8") as f:
                    f.write(f"# {title}\n\n原始链接：{url}\n")
                return full
            except Exception:
                return None

    if text is not None:
        # 文本统一导出 Markdown；缺失标题时补全
        content = text
        if not content.lstrip().startswith("#"):
            content = f"# {title}\n\n{text}"
        with open(full, "w", encoding="utf-8") as f:
            f.write(content)
        return full
    return None


def download_all(items, out_root, discover_only=False):
    stats = {"file": 0, "folder": 0, "skip": 0, "fail": 0, "note": 0}
    os.makedirs(out_root, exist_ok=True)
    ok_path = os.path.join(out_root, "_download_ok.txt")
    done = set()
    if os.path.exists(ok_path):
        with open(ok_path, "r", encoding="utf-8") as f:
            for line in f:
                done.add(line.strip())
    log_f = open(os.path.join(out_root, "_download_log.txt"), "a", encoding="utf-8")
    ok_f = open(ok_path, "a", encoding="utf-8")

    for it in items:
        if it["type"] == "folder":
            os.makedirs(os.path.join(out_root, it["rel"]), exist_ok=True)
            stats["folder"] += 1
            continue
        mt = it["media_type"]
        title = sanitize(it["title"])
        media_id = it["media_id"]
        out_dir = os.path.join(out_root, it["rel"])
        os.makedirs(out_dir, exist_ok=True)
        full = os.path.join(out_dir, title + ".md")
        if os.path.exists(full):
            cnt = 1
            root = os.path.splitext(full)[0]
            while os.path.exists(f"{root}_{cnt}.md"):
                cnt += 1
            full = f"{root}_{cnt}.md"
        key = media_id or (it["rel"] + "/" + title)
        if key in done:
            stats["skip"] += 1
            log_f.write(f"SKIP {media_id} {it['rel']}/{title}\n")
            continue
        if discover_only:
            print(f"[DISCOVER] {MEDIA_NAME.get(mt, mt)} | {it['rel']}/{title} | {media_id}")
            stats["file"] += 1
            if mt == 11:
                stats["note"] += 1
            continue
        try:
            res = fetch_content(media_id)
            saved = save_content(res, full, mt, it["title"])
            if saved:
                stats["file"] += 1
                if mt == 11:
                    stats["note"] += 1
                ok_f.write(key + "\n")
                ok_f.flush()
                log_f.write(f"OK {media_id} -> {saved}\n")
            else:
                stats["fail"] += 1
                log_f.write(f"FAIL {media_id} {it['rel']}/{title} (no content)\n")
        except Exception as e:
            stats["fail"] += 1
            log_f.write(f"ERROR {media_id} {it['rel']}/{title}: {e}\n")
        time.sleep(0.2)

    log_f.close()
    ok_f.close()
    return stats


def resolve_kb_id(arg_kb, arg_search):
    if arg_kb:
        return arg_kb
    if not arg_search:
        raise SystemExit("必须提供 --kb-id 或 --search")
    res = search_kb(arg_search)
    if isinstance(res, str):
        res = json.loads(res)
    items = (res or {}).get("info_list", []) or (res or {}).get("knowledge_base_list", []) or (res or {}).get("list", [])
    if not items:
        raise SystemExit(f"未找到知识库：{arg_search}")
    # 优先精确匹配
    for it in items:
        nm = it.get("name") or it.get("knowledge_base_name") or ""
        if arg_search == nm or arg_search in nm:
            return it.get("id") or it.get("knowledge_base_id")
    it = items[0]
    return it.get("id") or it.get("knowledge_base_id")


def main():
    ap = argparse.ArgumentParser(description="批量下载 IMA 知识库")
    ap.add_argument("--kb-id", help="知识库 ID（与 --search 二选一）")
    ap.add_argument("--search", help="按名称搜索知识库并取首个匹配 ID")
    ap.add_argument("--out", required=True, help="输出目录（按层级建子目录）")
    ap.add_argument("--discover", action="store_true", help="仅列出清单不下载")
    # 通道覆盖（一般无需填，自动从环境读取；仅当自行搭建 IMA-MCP 时指定）
    ap.add_argument("--mcp-url", help="IMA-MCP 端点 URL（覆盖自动检测）")
    ap.add_argument("--mcp-auth", help="IMA-MCP 鉴权头，如 Bearer xxxx")
    ap.add_argument("--mcp-session", help="会话 ID（connector-proxy 需要）")
    ap.add_argument("--mcp-prefix", help="工具命名空间前缀，默认 ima-mcp_")
    args = ap.parse_args()

    setup_proxy({
        "url": args.mcp_url, "auth": args.mcp_auth,
        "session": args.mcp_session, "prefix": args.mcp_prefix,
    })
    init()
    kb_id = resolve_kb_id(args.kb_id, args.search)
    print(f"目标知识库 ID: {kb_id}", flush=True)

    items = []
    walk(kb_id, None, "", items)
    print(f"遍历完成，共 {len(items)} 个条目", flush=True)

    if args.discover:
        from collections import Counter
        c = Counter((i["type"], i.get("media_type")) for i in items)
        for k, v in sorted(c.items()):
            print(k, v)
        download_all(items, args.out, discover_only=True)
        return

    stats = download_all(items, args.out, discover_only=False)
    print("DONE:", json.dumps(stats, ensure_ascii=False))


if __name__ == "__main__":
    main()
